package com.cryptostrategy.platform.backtesting.internal;
import static org.junit.jupiter.api.Assertions.*;import com.cryptostrategy.platform.backtesting.api.model.*;import com.cryptostrategy.platform.strategy.api.Strategy;import com.cryptostrategy.platform.strategy.api.model.*;import java.math.BigDecimal;import java.util.Map;import org.junit.jupiter.api.Test;
class BacktestFingerprintV1Test{@Test void excludesRuntimeIdsButChangesWhenFrozenAssumptionsChange(){BacktestTestFixture f=new BacktestTestFixture();Strategy hold=c->new StrategyDecision(StrategySignal.HOLD,c.evaluationTime(),f.reference,"HOLD","test",Map.of());var engine=new DeterministicBacktestEngine();var a=engine.run(f.command(1),f.reader(),hold);var same=engine.run(f.command(3),f.reader(),hold);assertNotEquals(a.resultId(),same.resultId());assertEquals(a.fingerprint(),same.fingerprint());var base=f.command(1);var changed=new ResolvedBacktestRun(base.experimentId(),base.candidateId(),base.jobId(),base.attemptId(),base.dataset(),base.provenance(),BacktestAssumptions.mvp(new BigDecimal("2000"),new BigDecimal("0.001"),new BigDecimal("0.001")),1,3);assertNotEquals(a.fingerprint(),engine.run(changed,f.reader(),hold).fingerprint());}}
